<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {authApi,currentAccount,clearSession} from '../../api/auth'
import {reviews,roleNames} from '../../api/accountReviews'
import {ApiError} from '../../api/http'
import AppSelect from '../../components/common/AppSelect.vue'
const router=useRouter(),busy=ref(false),error=ref(''),role=ref('user'),note=ref('')
async function refresh(){busy.value=true;error.value='';try{const a=await authApi.me();role.value=a.requested_role||'user';note.value=a.application_note||'';if(a.status==='active')await router.replace('/operations')}catch(e){if(e instanceof ApiError&&[401,403].includes(e.status)){clearSession();await router.replace({path:'/login',query:{reason:'review_changed'}})}else error.value=e instanceof Error?e.message:'读取失败'}finally{busy.value=false}}
async function reapply(){busy.value=true;error.value='';try{currentAccount.value=await reviews.reapply({version:currentAccount.value?.application_version,requested_role:role.value,application_note:note.value.trim()})}catch(e){error.value=e instanceof Error?e.message:'提交失败'}finally{busy.value=false}}
async function logout(){try{await authApi.logout()}catch{/* 失效会话也可退出 */}finally{await router.replace('/login')}}
onMounted(refresh)
</script>
<template><main class="application-page"><section class="card application-card"><span class="application-brand">禾龄通 · 员工岗位申请</span><h1>{{ currentAccount?.status==='rejected'?'请补充申请资料':'岗位申请已提交' }}</h1><p>{{ currentAccount?.name }}，{{ currentAccount?.status==='rejected'?'本次申请未通过，请根据院长的意见调整后重新提交。':'院长正在核对您的身份与岗位。通过审核并重新登录后，即可进入对应工作台。' }}</p><div class="application-summary"><b>申请岗位：{{ roleNames[currentAccount?.requested_role||'user'] }}</b><span>当前状态：{{ currentAccount?.status==='rejected'?'未通过':'待审核' }}</span></div><p v-if="currentAccount?.review_note" class="application-review">审核意见：{{ currentAccount.review_note }}</p><p v-if="error" class="application-error" role="alert">{{ error }}</p><form v-if="currentAccount?.status==='rejected'" @submit.prevent="reapply"><fieldset :disabled="busy"><label>申请岗位<AppSelect v-model="role" class="select"><option v-for="id in ['user','medical','kitchen','nursing','finance']" :key="id" :value="id">{{ roleNames[id] }}</option></AppSelect></label><label>补充说明<textarea v-model="note" class="input" rows="3" maxlength="500"/></label><button class="btn primary">重新提交申请</button></fieldset></form><div class="application-actions"><button class="btn" :disabled="busy" @click="refresh">{{ busy?'正在读取…':'刷新审核状态' }}</button><button class="btn" :disabled="busy" @click="logout">退出登录</button></div><p class="application-help">审核前无法查看老人档案、餐食、工资或其他业务资料。请联系院长核实任职信息，无需重复注册。</p></section></main></template>
<style scoped>.application-page{min-height:100vh;display:grid;place-items:center;padding:28px;background:linear-gradient(130deg,#edf3ff,#f8faff)}.application-card{width:100%;max-width:600px;padding:36px;box-sizing:border-box}.application-brand{color:var(--brand);font-weight:600}.application-card h1{font-size:26px;margin:24px 0 18px}.application-card p{line-height:1.9;color:#526481}.application-summary{display:grid;gap:12px;padding:20px;background:#f0f5ff;border-radius:12px;margin:24px 0}.application-actions{display:flex;gap:12px;margin:24px 0;flex-wrap:wrap}.application-help{font-size:13px}.application-review{border-left:3px solid #d99927;padding:12px;background:#fff8e8}.application-card .application-error{color:#a12d2d}fieldset{padding:0;border:0;min-width:0}label{display:grid;gap:8px;margin:18px 0}.btn{min-height:44px}@media(max-width:600px){.application-card{padding:24px}.application-page{padding:16px}}</style>
